sp_widget.client_script:
api.controller = function ($scope, $element, $timeout, $window, spUtil) {
    /* ======================================================================
     * EDP Quick Links — client controller
     * ======================================================================
     * Disclosure-dropdown behaviour for the header presentation.
     *
     *   c.open                 panel visibility (drives aria-expanded)
     *   c.toggle()             open/close from the trigger
     *   c.close(returnFocus)   close, optionally moving focus back to the
     *                          trigger
     *   c.onToggleKeydown()    Esc closes; ArrowDown opens and focuses item 1
     *   c.onMenuKeydown()      Esc / ArrowDown / ArrowUp / Home / End and
     *                          "tabbed past the last link" handling
     *
     * Outside clicks and focus leaving the component both close the panel.
     * No continuous animation is started here; the open/close motion is a
     * short CSS transition that is disabled under prefers-reduced-motion.
     *
     * NOTE: this file must begin with the `api.controller` assignment — the
     * SDK client-controller validator rejects a leading file-level comment
     * here, so the documentation lives inside the function body.
     * ====================================================================== */
    var c = this;

    var KEY_ESC = 27;
    var KEY_UP = 38;
    var KEY_DOWN = 40;
    var KEY_HOME = 36;
    var KEY_END = 35;
    var KEY_TAB = 9;

    c.uid = spUtil && spUtil.generateUniqueID ? spUtil.generateUniqueID() : ('edp' + Date.now());
    c.open = false;

    var root = $element[0];
    var doc = $window.document;

    function links() {
        return root.querySelectorAll('.edp-quicklinks-menu .edp-quicklink');
    }

    function toggleButton() {
        return root.querySelector('.edp-quicklinks-toggle');
    }

    function focusLink(index) {
        // The panel is created by ng-if, so wait for the digest to paint it.
        $timeout(function () {
            var nodes = links();
            if (!nodes.length) {
                return;
            }
            var i = Math.max(0, Math.min(index, nodes.length - 1));
            nodes[i].focus();
        });
    }

    c.close = function (returnFocus) {
        if (!c.open) {
            return;
        }
        c.open = false;
        if (returnFocus) {
            var btn = toggleButton();
            if (btn) {
                btn.focus();
            }
        }
    };

    c.toggle = function () {
        c.open = !c.open;
        if (c.open) {
            focusLink(0);
        }
    };

    c.onToggleKeydown = function ($event) {
        if (!$event) {
            return;
        }
        var code = $event.keyCode || $event.which;
        if (code === KEY_ESC) {
            $event.preventDefault();
            c.close(true);
        } else if (code === KEY_DOWN) {
            $event.preventDefault();
            if (!c.open) {
                c.open = true;
            }
            focusLink(0);
        }
    };

    c.onMenuKeydown = function ($event) {
        if (!$event) {
            return;
        }
        var code = $event.keyCode || $event.which;
        var nodes = links();
        var current = -1;
        var i;

        for (i = 0; i < nodes.length; i++) {
            if (nodes[i] === doc.activeElement) {
                current = i;
                break;
            }
        }

        if (code === KEY_ESC) {
            $event.preventDefault();
            c.close(true);
        } else if (code === KEY_DOWN) {
            $event.preventDefault();
            focusLink(current + 1 >= nodes.length ? 0 : current + 1);
        } else if (code === KEY_UP) {
            $event.preventDefault();
            focusLink(current <= 0 ? nodes.length - 1 : current - 1);
        } else if (code === KEY_HOME) {
            $event.preventDefault();
            focusLink(0);
        } else if (code === KEY_END) {
            $event.preventDefault();
            focusLink(nodes.length - 1);
        } else if (code === KEY_TAB && !$event.shiftKey && current === nodes.length - 1) {
            // Tabbing past the last link leaves the component — close behind us.
            c.close(false);
        }
    };

    // Outside click / focus-out both dismiss the panel.
    function onDocumentPointerDown(event) {
        if (!c.open || root.contains(event.target)) {
            return;
        }
        $scope.$applyAsync(function () {
            c.close(false);
        });
    }

    function onFocusOut() {
        $timeout(function () {
            if (c.open && !root.contains(doc.activeElement)) {
                c.close(false);
            }
        });
    }

    doc.addEventListener('mousedown', onDocumentPointerDown, true);
    root.addEventListener('focusout', onFocusOut);

    // $scope is injected ONLY for the destroy hook and the outside-click digest.
    $scope.$on('$destroy', function () {
        doc.removeEventListener('mousedown', onDocumentPointerDown, true);
        root.removeEventListener('focusout', onFocusOut);
    });
};

sp_widget.css:
/* ==========================================================================
 * EDP Quick Links — styles (HEADER presentation)
 * ==========================================================================
 * Compact navbar disclosure dropdown: a pill trigger in the header, a
 * frosted-glass panel of links below it. On tablet/phone the panel renders
 * inline inside the collapsed hamburger region instead of floating.
 *
 * Colours come from the theme `--edp-*` runtime tokens, so the component
 * re-themes instantly when `data-edp-theme` flips on <html>. Sizes and
 * spacing come from the theme $sp-* scales. Nothing below $sp-text-xs.
 * ========================================================================== */

.edp-quicklinks {
    position: relative;
    display: flex;
    align-items: center;
    padding: $sp-space-2;
}

/* ---------------- TRIGGER --------------------------------------------- */
.edp-quicklinks-toggle {
    display: inline-flex;
    align-items: center;
    gap: $sp-space-2;
    height: 34px;
    padding: 0 $sp-space-3;
    border-radius: var(--edp-radius-pill);
    border: 1px solid var(--edp-hairline-strong);
    background-color: var(--edp-surface-strong);
    color: var(--edp-text);
    font-size: $sp-text-sm;
    font-weight: 600;
    line-height: 1;
    white-space: nowrap;
    transition: background-color 180ms ease, border-color 180ms ease, color 180ms ease;
}

.edp-quicklinks-toggle:hover,
.edp-quicklinks-toggle:focus {
    background-color: var(--edp-accent-soft);
    border-color: var(--edp-accent);
    color: var(--edp-accent-ink);
}

.edp-quicklinks.is-open .edp-quicklinks-toggle {
    background-color: var(--edp-accent-soft-hover);
    border-color: var(--edp-accent);
    color: var(--edp-accent-ink);
}

.edp-quicklinks-toggle-icon {
    font-size: $sp-icon-xs;
    color: var(--edp-accent-ink);
}

.edp-quicklinks-caret {
    font-size: $sp-icon-xs;
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-quicklinks.is-open .edp-quicklinks-caret {
    transform: rotate(180deg);
}

/* ---------------- PANEL ----------------------------------------------- */
.edp-quicklinks-menu {
    position: absolute;
    top: calc(100% + #{$sp-space-1});
    right: 0;
    z-index: 1040;
    min-width: 260px;
    max-width: 320px;
    margin: 0;
    padding: $sp-space-2;
    list-style: none;
    border-radius: var(--edp-radius);
    border: 1px solid var(--edp-hairline);
    background-color: var(--edp-glass-surface);
    box-shadow: var(--edp-shadow-2);
    -webkit-backdrop-filter: blur(var(--edp-blur-strong)) saturate(150%);
    backdrop-filter: blur(var(--edp-blur-strong)) saturate(150%);
}

@supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {
    .edp-quicklinks-menu {
        background-color: var(--edp-surface-strong);
    }
}

.edp-quicklinks-head {
    padding: $sp-space-2 $sp-space-3;
    color: var(--edp-text-muted);
    font-size: $sp-text-xs;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.edp-quicklink-item {
    display: block;
}

.edp-quicklink {
    display: flex;
    align-items: center;
    gap: $sp-space-3;
    padding: $sp-space-2 $sp-space-3;
    border-radius: var(--edp-radius-sm);
    color: var(--edp-text);
    text-decoration: none;
    transition: background-color 180ms ease, color 180ms ease;
}

.edp-quicklink:hover,
.edp-quicklink:focus {
    background-color: var(--edp-accent-soft);
    color: var(--edp-text);
    text-decoration: none;
}

.edp-quicklink-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    width: 28px;
    height: 28px;
    border-radius: var(--edp-radius-sm);
    background-color: var(--edp-accent-soft);
    color: var(--edp-accent-ink);
    font-size: $sp-icon-xs;
}

.edp-quicklink:hover .edp-quicklink-icon,
.edp-quicklink:focus .edp-quicklink-icon {
    background-color: var(--edp-accent-soft-hover);
}

.edp-quicklink-label {
    flex: 1 1 auto;
    font-size: $sp-text-sm;
    font-weight: 600;
    line-height: 1.4;
}

.edp-quicklink-chevron {
    flex: 0 0 auto;
    color: var(--edp-accent-ink);
    font-size: $sp-icon-xs;
    transition: transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.edp-quicklink:hover .edp-quicklink-chevron,
.edp-quicklink:focus .edp-quicklink-chevron {
    transform: translateX(3px);
}

/* ---------------- COLLAPSED (HAMBURGER) REGION ------------------------
 * Inside the collapsed navbar the panel must not float over the page: it
 * becomes a full-width inline block that pushes the rest of the collapsed
 * nav down, exactly like the nav links themselves.
 * ------------------------------------------------------------------- */
@media (max-width: 992px) {
    .edp-quicklinks {
        display: block;
        width: 100%;
        padding: $sp-space-2 $sp-space-3;
    }

    .edp-quicklinks-toggle {
        width: 100%;
        justify-content: space-between;
        height: 38px;
    }

    .edp-quicklinks-menu {
        position: static;
        width: 100%;
        max-width: none;
        margin-top: $sp-space-2;
        box-shadow: none;
        background-color: var(--edp-surface-sunken);
    }
}

/* ---------------- REDUCED MOTION (MANDATORY) ------------------------- */
@media (prefers-reduced-motion: reduce) {
    .edp-quicklinks-toggle,
    .edp-quicklinks-caret,
    .edp-quicklink,
    .edp-quicklink-icon,
    .edp-quicklink-chevron {
        transition: none;
    }

    .edp-quicklink:hover .edp-quicklink-chevron,
    .edp-quicklink:focus .edp-quicklink-chevron {
        transform: none;
    }
}

sp_widget.script:
/* ==========================================================================
 * EDP Quick Links — server script
 * ==========================================================================
 * Six configurable link slots. A slot with an empty label is skipped, so the
 * grid can hold anywhere between 0 and 6 links without a code change.
 *
 * Scoped app: gs.info / gs.error only, new GlideDateTime(), explicit
 * GlideRecord. No gs.print / nowDateTime() / implicit `current`.
 * ========================================================================== */
(function () {

    data.heading = '';
    data.subheading = '';
    data.links = [];

    data.heading = options.heading || gs.getMessage('Quick links');
    data.subheading = options.subheading || gs.getMessage('The shortcuts people use most.');

    var LINK_COUNT = 6;

    var FALLBACKS = {
        1: { label: gs.getMessage('Browse the catalog'), icon: 'th-large', url: '?id=sc_landing' },
        2: { label: gs.getMessage('My requests'), icon: 'inbox', url: '?id=requests' },
        3: {
            label: gs.getMessage('Change Review Board'),
            icon: 'check-square-o',
            url: '?id=sc_cat_item&sys_id=7518ecedb14542a59ccfc62d5058a8d5'
        },
        4: {
            label: gs.getMessage('Change Deployment'),
            icon: 'rocket',
            url: '?id=sc_cat_item&sys_id=9639f638440e4833b8b56ec59845cec4'
        },
        5: {
            label: gs.getMessage('Change Management'),
            icon: 'sitemap',
            url: '?id=sc_category&sys_id=89f36964102a4613a251b004e0c8beed'
        },
        // Slot 6 ships empty on purpose — an admin can fill it in without
        // touching code.
        6: { label: '', icon: 'link', url: '' }
    };

    function isTruthy(value) {
        return value === true || value === 'true' || value === 1 || value === '1';
    }

    for (var i = 1; i <= LINK_COUNT; i++) {
        var prefix = 'link' + i + '_';
        var fallback = FALLBACKS[i] || { label: '', icon: 'link', url: '' };

        var label = options[prefix + 'label'];
        label = (label === undefined || label === null) ? fallback.label : (label + '');
        label = label.trim();

        if (!label) {
            continue; // blank slot — skip it
        }

        var url = options[prefix + 'url'] || fallback.url;
        if (!url) {
            gs.info('[EDP quick links] Slot ' + i + ' has a label but no URL — skipping.');
            continue;
        }

        data.links.push({
            id: 'link' + i,
            label: label,
            icon: options[prefix + 'icon'] || fallback.icon || 'link',
            url: url + '',
            external: isTruthy(options[prefix + 'external'])
        });
    }
})();
